examples.code:
PRAGMA foreign_keys = ON;
CREATE TABLE c4_student (student_id INTEGER PRIMARY KEY, student_name TEXT NOT NULL);
CREATE TABLE c4_course (course_id INTEGER PRIMARY KEY, course_title TEXT NOT NULL);
CREATE TABLE c4_enrollment (
  student_id INTEGER NOT NULL,
  course_id INTEGER NOT NULL,
  PRIMARY KEY (student_id, course_id),
  FOREIGN KEY (student_id) REFERENCES c4_student(student_id) ON UPDATE CASCADE ON DELETE CASCADE,
  FOREIGN KEY (course_id) REFERENCES c4_course(course_id) ON UPDATE CASCADE ON DELETE RESTRICT
);
INSERT INTO c4_student VALUES (1, 'Mina');
INSERT INTO c4_course VALUES (10, 'SQL Basics');
INSERT INTO c4_enrollment VALUES (1, 10);
UPDATE c4_student SET student_id = 2 WHERE student_id = 1;
SELECT student_id, course_id FROM c4_enrollment;
DELETE FROM c4_student WHERE student_id = 2;
SELECT COUNT(*) FROM c4_enrollment;

practice.starterCode:
PRAGMA foreign_keys = ON;

CREATE TABLE c4_parent (department_id INTEGER PRIMARY KEY, department_name TEXT NOT NULL);

CREATE TABLE c4_child (employee_id INTEGER PRIMARY KEY, employee_name TEXT NOT NULL, department_id INTEGER, FOREIGN KEY (department_id) REFERENCES c4_parent(department_id));

INSERT INTO c4_parent VALUES (10, 'Research'); INSERT INTO c4_child VALUES (1, 'Uma', 10);

SELECT c.employee_name, p.department_name FROM c4_child AS c JOIN c4_parent AS p ON p.department_id = c.department_id;

